886	// Agregações determinísticas usadas pelo hook (puras, testáveis)
887	// ─────────────────────────────────────────────────────────────────────────────
888	
889	/** Linha mínima de `movimentacoes` necessária à agregação. */
890	export interface MovementRow {
891	  loja_id: number | null;
892	  tipo_movimentacao: string;
893	  data_movimentacao: string | null;
894	}
895	
896	/** Resultado por loja da agregação de movimentações do dia. */
897	export interface MovementAggregate {
898	  entradas: number;
899	  saidas: number;
900	  ultimaBipagem: string | null;
901	}
902	
903	/**
904	 * Agrega movimentações do dia por loja: contagem de entradas, saídas e
905	 * timestamp da última movimentação ("última bipagem"). Linhas sem loja
906	 * são ignoradas.
907	 */
908	export function aggregateMovements(
909	  rows: MovementRow[],
910	): Map<number, MovementAggregate> {
911	  const out = new Map<number, MovementAggregate>();
912	  for (const row of rows) {
913	    if (row.loja_id == null) continue;
914	    let agg = out.get(row.loja_id);
915	    if (!agg) {
916	      agg = { entradas: 0, saidas: 0, ultimaBipagem: null };
917	      out.set(row.loja_id, agg);
918	    }
919	    if (row.tipo_movimentacao === 'entrada') agg.entradas += 1;
920	    else if (row.tipo_movimentacao === 'saida') agg.saidas += 1;
921	    if (
922	      row.data_movimentacao &&
923	      (agg.ultimaBipagem === null || row.data_movimentacao > agg.ultimaBipagem)
924	    ) {
925	      agg.ultimaBipagem = row.data_movimentacao;
926	    }
927	  }
928	  return out;
929	}
930	
931	/**
932	 * Normaliza um valor de `produtos_master.setor` para comparação: trim,
933	 * minúsculas e remoção de acentos (NFD). O banco tem caixa/acentuação
934	 * inconsistentes no MESMO setor (ex.: "CÂMARA FRIA" e "Câmara Fria") —
935	 * toda comparação de setor DEVE passar por aqui.
936	 */
937	export function normalizeSetor(value: string | null | undefined): string {
938	  return (value ?? '')
939	    .normalize('NFD')
940	    .replace(/\p{M}/gu, '')
941	    .trim()
942	    .toLowerCase();
943	}
944	
945	/**
946	 * true quando o setor é o {@link TV_ALERT_SETOR} (igualdade EXATA após
947	 * {@link normalizeSetor} — nunca prefixo: "PRODUTOS DE LIMPEZA" NÃO conta).
948	 */
949	export function isTvAlertSetor(setor: string | null | undefined): boolean {
950	  return normalizeSetor(setor) === normalizeSetor(TV_ALERT_SETOR);
951	}
952	
953	/** Linha mínima de `estoque` (com nome do produto ativo já joinado). */
954	export interface StockRow {
955	  loja_id: number | null;
956	  quantidade_atual: number | null;
957	  quantidade_minima: number | null;
958	  produtoNome: string;
959	  /** `produtos_master.setor` cru (caixa/acentos inconsistentes no banco). */
960	  setor: string | null;
961	}
962	
963	/** Detalhe de alertas de estoque por loja. */
964	export interface StockDetail {
965	  zerados: number;
966	  abaixoMinimo: number;
967	  itens: TvStockAlertItem[];
968	}
969	
970	/**
971	 * Classifica linhas de estoque em alertas por loja (apenas produtos ATIVOS
972	 * devem chegar aqui — o JOIN com `produtos_master.ativo = true` é feito na
973	 * query). Regras (critério existente do projeto, sem schema novo):
974	 * - SÓ setor {@link TV_ALERT_SETOR} entra em alerta (regra do CTO
975	 *   2026-06-05: alertas só do setor de produtos vendáveis) — comparação
976	 *   normalizada client-side porque a caixa no banco é inconsistente;
977	 * - zerado (vermelho): quantidade ≤ 0 com mínimo definido (positivo);
978	 * - abaixo do mínimo (âmbar): quantidade entre 0 exclusivo e o mínimo.
979	 */
980	export function buildStockSummary(rows: StockRow[]): Map<number, StockDetail> {
981	  const out = new Map<number, StockDetail>();
982	  for (const row of rows) {
983	    if (row.loja_id == null) continue;
984	    if (!isTvAlertSetor(row.setor)) continue; // fora do setor vendável → sem alerta
985	    const min = row.quantidade_minima ?? 0;
986	    if (min <= 0) continue; // sem mínimo definido → sem alerta
987	    const qty = row.quantidade_atual ?? 0;
988	    if (qty >= min) continue; // dentro do normal
989	    let detail = out.get(row.loja_id);
990	    if (!detail) {
991	      detail = { zerados: 0, abaixoMinimo: 0, itens: [] };
992	      out.set(row.loja_id, detail);
993	    }
994	    const zerado = qty <= 0;
995	    if (zerado) detail.zerados += 1;
996	    else detail.abaixoMinimo += 1;
997	    detail.itens.push({
998	      produtoNome: row.produtoNome,
999	      quantidade: qty,
1000	      quantidadeMinima: min,
1001	      zerado,
1002	    });
1003	  }
1004	  return out;
1005	}
1006	
1007	/**
1008	 * Constrói as exceções de estoque (item × loja) a partir do detalhe por loja.
1009	 * Itens zerados viram exceção vermelha; abaixo do mínimo, âmbar.
1010	 */
1011	export function buildStockExceptions(
1012	  detailByLoja: Map<number, StockDetail>,
1013	  lojaNomeById: Map<number, string>,
1014	): TvException[] {
1015	  const out: TvException[] = [];
1016	  for (const [lojaId, detail] of detailByLoja) {
1017	    const lojaNome = lojaNomeById.get(lojaId) ?? `Loja ${lojaId}`;
1018	    for (const item of detail.itens) {
