1492	      const liveUpdatedAt = freshness.vendasLive.updatedAt;
1493	      allExceptions.push({
1494	        id: 'stale-data:vendas-live',
1495	        kind: 'stale-data',
1496	        severity: 'amber',
1497	        lojaId: null,
1498	        lojaNome: null,
1499	        message: liveUpdatedAt
1500	          ? `Venda live sem atualização desde ${new Date(liveUpdatedAt).toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' })}`
1501	          : 'Venda live ainda não carregou',
1502	      });
1503	    }
1504	    const exceptions = sortAndLimitExceptions(allExceptions);
1505	
1506	    // ── Hero (rede) ──
1507	    // Live: lojas degust com dado (caixa aberto ou fechado recentemente —
1508	    // a madrugada mostra o fechamento de ontem). Modo passado: lojas degust
1509	    // com total oficial no range selecionado.
1510	    const liveStores = stores.filter((s) => s.channel === 'degust-live' && s.vendas != null);
1511	    const vendasHoje = liveStores.reduce((s, st) => s + (st.vendas?.valor ?? 0), 0);
1512	    const totalCupons = liveStores.reduce((s, st) => s + (st.vendas?.cupons ?? 0), 0);
1513	    const ticketMedioRede = totalCupons > 0 ? vendasHoje / totalCupons : null;
1514	    // R$/hora: live = horas decorridas da janela de hoje; passado = janela
1515	    // COMPLETA (12h) × nº de dias do range (períodos já encerrados).
1516	    const businessFraction = businessDayFraction(now);
1517	    const horasDecorridas = isLive
1518	      ? businessFraction * 12 // janela 10h–22h = 12h
1519	      : 12 * rangeDayCount(range);
1520	    const valorPorHora = horasDecorridas > 0 && vendasHoje > 0
1521	      ? vendasHoje / horasDecorridas
1522	      : null;
1523	    const vendasPorHora = horasDecorridas > 0 && totalCupons > 0
1524	      ? totalCupons / horasDecorridas
1525	      : null;
1526	    const metasHoje = liveStores
1527	      .map((s) => s.metaDia)
1528	      .filter((m): m is number => m != null && m > 0);
1529	    const metaDia = metasHoje.length > 0 ? metasHoje.reduce((a, b) => a + b, 0) : null;
1530	
1531	    // Base do delta principal:
1532	    // - live: soma por loja do "dia anterior ao flash" PACEADO pela curva
1533	    //   horária real (R5) — fallback dia completo quando não há curva;
1534	    // - passado: total oficial do período equivalente anterior COMPLETO.
1535	    const prevNetworkBase = isLive
1536	      ? liveStores.reduce((sum, st) => {
1537	          const flash = flashByLoja.get(st.lojaId);
1538	          if (!flash) return sum;
1539	          const ft = parseBrDateTime(flash.ultima_atualizacao);
1540	          const fd = ft ? toIsoDateLocal(ft) : todayIso;
1541	          const pd = toIsoDateLocal(addDays(parseIsoDateLocal(fd), -1));
1542	          const prevVal =
1543	            dailyByLoja.get(st.lojaId)?.get(pd) ?? yesterdayByLoja.get(st.lojaId) ?? 0;
1544	          if (prevVal <= 0) return sum;
1545	          const pace = hourlyPaceBase(
1546	            prevVal,
1547	            hourlyByKey.get(`${st.lojaId}:${pd}`),
1548	            now,
1549	          );
1550	          return sum + (pace ?? prevVal);
1551	        }, 0)
1552	      : liveStores.reduce(
1553	          (sum, st) =>
1554	            sum + sumRange(rangeData?.dailyByLoja.get(st.lojaId), previousRange).total,
1555	          0,
1556	        );
1557	
1558	    const lastWeekTotal = liveStores.reduce((s, st) => {
1559	      const flash = flashByLoja.get(st.lojaId);
1560	      if (!flash) return s;
1561	      const ft = parseBrDateTime(flash.ultima_atualizacao);
1562	      const fd = ft ? toIsoDateLocal(ft) : todayIso;
1563	      const wd = toIsoDateLocal(addDays(parseIsoDateLocal(fd), -7));
1564	      return s + (dailyByLoja.get(st.lojaId)?.get(wd) ?? lastWeekByLoja.get(st.lojaId) ?? 0);
1565	    }, 0);
1566	    const network: TvNetworkSummary | null = ctx
1567	      ? {
1568	          vendasHoje,
1569	          ticketMedio: ticketMedioRede,
1570	          valorPorHora,
1571	          vendasPorHora,
1572	          totalCupons,
1573	          metaDia,
1574	          // Live: pró-rata da janela; passado dia: % do dia COMPLETO;
1575	          // passado semana/mês: sem meta agregada honesta → null.
1576	          pctMetaProRata: isLive
1577	            ? pctOfProRataTarget(vendasHoje, metaDia, now)
1578	            : period === 'today'
1579	              ? pctOfFullDayTarget(vendasHoje, metaDia)
1580	              : null,
1581	          // deltaSemana: só no live com period='week'
1582	          deltaSemana: isLive && period === 'week'
1583	            ? weekOverWeekDelta(
1584	                vendasHoje,
1585	                proRataDayBase(lastWeekTotal, now) ?? (lastWeekTotal || null),
1586	              )
1587	            : null,
1588	          // deltaOntem: live = vs dia anterior ao flash (base paceada);
1589	          // passado = vs período equivalente anterior completo
1590	          deltaOntem: relativeDelta(vendasHoje, prevNetworkBase || null),
1591	          // Totais da REDE: incluem linhas sem loja_id (não atribuíveis a
1592	          // nenhuma coluna — entram SOMENTE aqui).
1593	          perdas: {
1594	            valor: perdasAgg?.current.total.valor ?? 0,
1595	            itens: perdasAgg?.current.total.itens ?? 0,
1596	            deltaPct: relativeDelta(
1597	              perdasAgg?.current.total.valor ?? 0,
1598	              perdasAgg?.previous.total.valor ?? null,
1599	            ),
1600	          },
1601	          marketing: {
1602	            valor: marketingAgg?.current.total.valor ?? 0,
1603	            acoes: marketingAgg?.current.total.acoes ?? 0,
1604	            deltaPct: relativeDelta(
1605	              marketingAgg?.current.total.valor ?? 0,
1606	              marketingAgg?.previous.total.valor ?? null,
1607	            ),
1608	          },
1609	          alertasCriticos: allExceptions.filter((e) => e.severity === 'red').length,
1610	          lojasLive: liveStores.length,
1611	          lojasDefasadas: stores.filter((s) => s.channel === 'linx-lagged').length,
1612	        }
1613	      : null;
1614	
1615	    // ── Mês até agora (R3) + meta mensal com semanas redistribuídas (R4) ──
1616	    // Sempre o mês CORRENTE, independente do período/offset exibido.
1617	    let monthProgress: TvMonthProgress | null = null;
1618	    const mtd = mtdQuery.data;
1619	    if (mtd) {
