1621	      for (const valor of mtd.byDate.values()) mtdTotal += valor;
1622	      const metasMensais = metasMensaisQuery.data ?? [];
1623	      const redeRow = metasMensais.find((m) => m.lojaId === null);
1624	      const lojaRows = metasMensais.filter((m) => m.lojaId !== null);
1625	      // Meta da rede: linha loja_id NULL; fallback = soma das metas por loja
1626	      const metaMensal =
1627	        redeRow != null
1628	          ? redeRow.valorMeta
1629	          : lojaRows.length > 0
1630	            ? lojaRows.reduce((s, m) => s + m.valorMeta, 0)
1631	            : null;
1632	      const weeks =
1633	        metaMensal != null && metaMensal > 0
1634	          ? weeklyTargets(metaMensal, mtd.byDate, now)
1635	          : [];
1636	      monthProgress = {
1637	        mtdTotal,
1638	        metaMensal,
1639	        pctMeta:
1640	          metaMensal != null && metaMensal > 0
1641	            ? (mtdTotal / metaMensal) * 100
1642	            : null,
1643	        projection: monthEndProjection(mtdTotal, now),
1644	        weeks,
1645	        currentWeek: weeks.find((w) => w.isCurrent) ?? null,
1646	        mtdByLoja: mtd.byLoja,
1647	      };
1648	    }
1649	
1650	    return {
1651	      network,
1652	      stores,
1653	      factory,
1654	      exceptions,
1655	      freshness,
1656	      period,
1657	      offset: clampedOffset,
1658	      isLive,
1659	      range,
1660	      previousRange,
1661	      monthProgress,
1662	      deliverySplitToday: deliveryData,
1663	      hourlyCurves: hourlyQuery.data ?? [],
1664	      isLoading: ctxQuery.isLoading,
1665	      isError: ctxQuery.isError,
