1	/**
2	 * @module features/tv-dashboard/model/useTvReport
3	 *
4	 * Dados do RELATÓRIO MATINAL (R6 da spec `tv-acompanhamento-live`):
5	 * uma única chamada à edge `degust-pos-financial` cobrindo o mês do
6	 * dia-base (01 → dia-base, com quebra delivery do BSB) + `metas_mensais`
7	 * do mês. Deriva: faturamento do dia-base por loja e rede, MTD por loja
8	 * e rede, meta mensal + %, meta/realizado da semana corrente
9	 * (redistribuição de `weeklyTargets`) e projeção de fim de mês.
10	 *
11	 * SEM polling: o relatório é um snapshot sob demanda (modal aberto).
12	 * `buildTvReportText` é pura — testável sem I/O.
13	 */
14	
15	import { useQuery, useQueryClient, type QueryClient } from '@tanstack/react-query';
16	import { supabase } from '@/integrations/supabase/client';
17	import {
18	  TV_DELIVERY_SPLIT_LOJA_ID,
19	  monthEndProjection,
20	  parseIsoDateLocal,
21	  toIsoDateLocal,
22	  weeklyTargets,
23	} from './tvMath';
24	import type { TvWeeklyGoal } from './types';
25	import {
26	  TV_QUERY_INTERVALS,
27	  fetchTvContext,
28	  tvDashboardKeys,
29	} from './useTvDashboardData';
30	
31	// ─────────────────────────────────────────────────────────────────────────────
32	// Tipos
33	// ─────────────────────────────────────────────────────────────────────────────
34	
35	/** Linha por loja do relatório (dia-base + acumulado do mês). */
36	export interface TvReportLojaLine {
37	  lojaId: number;
38	  /** Nome curto (sem o prefixo "Momma "). */
39	  nome: string;
40	  /** R$ do dia-base (null = sem venda registrada no dia → "—"). */
41	  valorDia: number | null;
42	  /** R$ acumulado 01 → dia-base. */
43	  mtd: number;
44	}
45	
46	/** Snapshot derivado do relatório matinal. */
47	export interface TvReportData {
48	  /** Dia-base (YYYY-MM-DD). */
49	  baseDate: string;
50	  /** R$ da rede no dia-base. */
51	  totalDia: number;
52	  /** R$ da rede acumulado 01 → dia-base. */
53	  totalMtd: number;
54	  /** Lojas Degust ordenadas por faturamento do dia desc (sem venda no fim). */
55	  lojas: TvReportLojaLine[];
56	  /** Quebra do BSB Shopping no dia-base (null sem cupom delivery). */
57	  deliverySplit: { delivery: number; balcao: number } | null;
58	  /** Meta mensal da rede (linha NULL; fallback soma por loja), ou null. */
59	  metaMensal: number | null;
60	  /** % da meta mensal já realizada, ou null sem meta. */
61	  pctMeta: number | null;
62	  /** Semana corrente (contendo o dia-base) com meta redistribuída, ou null. */
63	  currentWeek: TvWeeklyGoal | null;
64	  /** Projeção de fim de mês por run-rate até o dia-base. */
65	  projection: number;
66	}
67	
68	/** Resposta da edge `degust-pos-financial` (campos usados no relatório). */
69	interface DegustReportResponse {
70	  daily?: Array<{
71	    data: string;
72	    loja_id: number;
73	    total_faturado: number;
74	    total_cupons: number;
75	  }>;
76	  deliverySplit?: Array<{
77	    data: string;
78	    loja_id: number;
79	    total_delivery: number;
80	    cupons_delivery: number;
81	  }>;
82	}
83	
84	// ─────────────────────────────────────────────────────────────────────────────
85	// Fetch + derivação
86	// ─────────────────────────────────────────────────────────────────────────────
87	
88	async function fetchTvReport(
89	  baseDateIso: string,
90	  queryClient: QueryClient,
91	): Promise<TvReportData> {
92	  const base = parseIsoDateLocal(baseDateIso);
93	  const monthStart = toIsoDateLocal(
94	    new Date(base.getFullYear(), base.getMonth(), 1),
95	  );
96	
97	  // Contexto compartilhado com o painel: ensureQueryData reusa o cache da
98	  // query principal (mesma key + mesmo staleTime) em vez de refazer o fetch
99	  // a cada relatório.
100	  const ctx = await queryClient.ensureQueryData({
101	    queryKey: tvDashboardKeys.context(),
102	    queryFn: fetchTvContext,
103	    staleTime: TV_QUERY_INTERVALS.slowMs,
104	  });
105	  const [edgeRes, metasRes] = await Promise.all([
106	    supabase.functions.invoke('degust-pos-financial', {
107	      body: {
108	        startDate: monthStart,
109	        endDate: baseDateIso,
110	        includeDeliverySplit: true,
111	        deliveryLojaId: TV_DELIVERY_SPLIT_LOJA_ID,
112	      },
113	    }),
114	    supabase
115	      .from('metas_mensais')
116	      .select('loja_id, valor_meta')
117	      .eq('ano', base.getFullYear())
118	      .eq('mes', base.getMonth() + 1),
119	  ]);
120	  if (edgeRes.error) {
121	    throw new Error(
122	      `[tv-report] degust-pos-financial: ${edgeRes.error.message ?? 'falha na edge'}`,
123	    );
124	  }
125	  const edge = (edgeRes.data ?? {}) as DegustReportResponse;
126	  // Meta ausente não derruba o relatório (mesma tolerância do painel)
127	  const metasRows = metasRes.error ? [] : (metasRes.data ?? []);
128	
129	  // Agregações: dia-base por loja, MTD por loja e por data (rede)
130	  const dayByLoja = new Map<number, number>();
131	  const mtdByLoja = new Map<number, number>();
132	  const redeByDate = new Map<string, number>();
133	  for (const d of edge.daily ?? []) {
134	    if (!ctx.degustLojaIds.has(d.loja_id)) continue;
135	    if (d.data > baseDateIso) continue;
136	    const valor = d.total_faturado ?? 0;
137	    mtdByLoja.set(d.loja_id, (mtdByLoja.get(d.loja_id) ?? 0) + valor);
138	    redeByDate.set(d.data, (redeByDate.get(d.data) ?? 0) + valor);
139	    if (d.data === baseDateIso) {
140	      dayByLoja.set(d.loja_id, (dayByLoja.get(d.loja_id) ?? 0) + valor);
141	    }
142	  }
143	  let totalDia = 0;
144	  for (const v of dayByLoja.values()) totalDia += v;
145	  let totalMtd = 0;
146	  for (const v of mtdByLoja.values()) totalMtd += v;
147	
148	  // Linhas por loja (Degust), ordenadas por faturamento do dia desc;
149	  // lojas sem venda no dia ("—") vão pro fim, ordenadas por MTD.
150	  const lojas: TvReportLojaLine[] = ctx.lojas
151	    .filter((l) => ctx.degustLojaIds.has(l.id))
152	    .map((l) => ({
153	      lojaId: l.id,
154	      nome: l.nome.replace(/^Momma\s+/i, ''),
155	      valorDia: dayByLoja.has(l.id) ? (dayByLoja.get(l.id) ?? 0) : null,
156	      mtd: mtdByLoja.get(l.id) ?? 0,
157	    }))
158	    .sort((a, b) => (b.valorDia ?? -1) - (a.valorDia ?? -1) || b.mtd - a.mtd);
159	
160	  // Quebra delivery do BSB no dia-base (balcão = total oficial − delivery)
161	  const splitRow = (edge.deliverySplit ?? []).find(
162	    (r) => r.data === baseDateIso && r.loja_id === TV_DELIVERY_SPLIT_LOJA_ID,
163	  );
164	  const bsbDia = dayByLoja.get(TV_DELIVERY_SPLIT_LOJA_ID);
165	  const deliverySplit =
166	    splitRow != null && bsbDia != null
167	      ? {
168	          delivery: splitRow.total_delivery,
169	          balcao: Math.max(0, bsbDia - splitRow.total_delivery),
170	        }
171	      : null;
172	
173	  // Meta mensal: linha da rede (loja_id NULL); fallback = soma por loja
174	  const redeRow = metasRows.find((m) => m.loja_id === null);
175	  const lojaRows = metasRows.filter((m) => m.loja_id !== null);
176	  const metaMensal =
177	    redeRow != null
178	      ? redeRow.valor_meta
179	      : lojaRows.length > 0
180	        ? lojaRows.reduce((s, m) => s + m.valor_meta, 0)
181	        : null;
182	
183	  // Semana corrente (contendo o dia-base) com redistribuição (R4)
184	  const weeks =
185	    metaMensal != null && metaMensal > 0
186	      ? weeklyTargets(metaMensal, redeByDate, base)
187	      : [];
188	
189	  return {
190	    baseDate: baseDateIso,
191	    totalDia,
192	    totalMtd,
193	    lojas,
194	    deliverySplit,
195	    metaMensal,
196	    pctMeta:
197	      metaMensal != null && metaMensal > 0 ? (totalMtd / metaMensal) * 100 : null,
198	    currentWeek: weeks.find((w) => w.isCurrent) ?? null,
199	    projection: monthEndProjection(totalMtd, base),
200	  };
201	}
202	
203	// ─────────────────────────────────────────────────────────────────────────────
204	// Texto do relatório (pura — formato pt-BR pronto pra WhatsApp)
205	// ─────────────────────────────────────────────────────────────────────────────
206	
207	/** R$ inteiro pt-BR ("R$ 9.999") — relatório não usa centavos. */
208	function brl(value: number): string {
209	  return `R$ ${Math.round(value).toLocaleString('pt-BR')}`;
210	}
211	
212	/** "quarta, 10/06/2026" (weekday longo sem o sufixo "-feira"). */
213	function formatLongDate(date: Date): string {
214	  const weekday = date
215	    .toLocaleDateString('pt-BR', { weekday: 'long' })
216	    .replace('-feira', '');
217	  return `${weekday}, ${date.toLocaleDateString('pt-BR')}`;
218	}
219	
220	/**
221	 * Monta o texto do relatório matinal (R6). `todayIso` injetável para
222	 * teste: define se o dia-base é "ontem" (rótulo padrão do relatório)
223	 * ou outro dia ("Faturamento do dia").
224	 */
225	export function buildTvReportText(
226	  report: TvReportData,
227	  todayIso: string = toIsoDateLocal(new Date()),
228	): string {
229	  const base = parseIsoDateLocal(report.baseDate);
230	  const yesterdayOfToday = toIsoDateLocal(
231	    new Date(parseIsoDateLocal(todayIso).getTime() - 86_400_000),
232	  );
233	  const isYesterday = report.baseDate === yesterdayOfToday;
234	  const dd = String(base.getDate()).padStart(2, '0');
235	  const mm = String(base.getMonth() + 1).padStart(2, '0');
236	
237	  const lines: string[] = [];
238	  lines.push('📊 *Momma — Relatório Diário*');
239	  lines.push(`🗓 ${formatLongDate(base)}`);
240	  lines.push('');
241	  lines.push(
242	    `*Faturamento ${isYesterday ? 'de ontem' : 'do dia'}:* ${brl(report.totalDia)}`,
243	  );
244	  for (const loja of report.lojas) {
245	    let line = `• ${loja.nome}: ${loja.valorDia != null ? brl(loja.valorDia) : '—'}`;
246	    if (
247	      loja.lojaId === TV_DELIVERY_SPLIT_LOJA_ID &&
248	      report.deliverySplit != null &&
249	      loja.valorDia != null
250	    ) {
251	      line += ` (loja ${brl(report.deliverySplit.balcao)} · delivery ${brl(report.deliverySplit.delivery)})`;
252	    }
253	    lines.push(line);
254	  }
255	  lines.push('');
256	  const metaPart =
257	    report.pctMeta != null && report.metaMensal != null
258	      ? ` • ${Math.round(report.pctMeta)}% da meta de ${brl(report.metaMensal)}`
259	      : '';
260	  lines.push(`*Mês (01–${dd}/${mm}):* ${brl(report.totalMtd)}${metaPart}`);
261	  for (const loja of [...report.lojas].sort((a, b) => b.mtd - a.mtd)) {
262	    lines.push(`• ${loja.nome}: ${loja.mtd > 0 ? brl(loja.mtd) : '—'}`);
263	  }
264	  lines.push('');
265	  if (report.currentWeek) {
266	    const pct =
267	      report.currentWeek.target > 0
268	        ? Math.round(
269	            ((report.currentWeek.achieved ?? 0) / report.currentWeek.target) * 100,
270	          )
271	        : 0;
272	    lines.push(
273	      `*Semana atual:* ${brl(report.currentWeek.achieved ?? 0)} / meta ${brl(report.currentWeek.target)} (${pct}%)`,
274	    );
275	  }
276	  lines.push(`*Projeção fim do mês:* ${brl(report.projection)}`);
277	  return lines.join('\n');
278	}
279	
280	// ─────────────────────────────────────────────────────────────────────────────
281	// Hook
282	// ─────────────────────────────────────────────────────────────────────────────
283	
284	/**
285	 * Snapshot do relatório matinal para o dia-base. UMA chamada à edge por
286	 * dia-base (sem polling — `staleTime` longo; refetch só por troca de data
287	 * ou reabertura após GC do cache).
288	 *
289	 * @param baseDateIso - Dia-base (YYYY-MM-DD), tipicamente ontem.
290	 * @param enabled - true apenas com o modal aberto (não busca à toa).
291	 */
292	export function useTvReport(baseDateIso: string, enabled: boolean) {
293	  const queryClient = useQueryClient();
