45	
46	  const handleCopy = async () => {
47	    if (!text) return;
48	    try {
49	      await navigator.clipboard.writeText(text);
50	      toast.success('Relatório copiado');
51	    } catch {
52	      toast.error('Não foi possível copiar', {
53	        description: 'Selecione o texto do preview e copie manualmente.',
54	      });
55	    }
56	  };
57	
58	  const handleWhatsApp = () => {
59	    if (!text) return;
60	    window.open(
61	      `https://wa.me/?text=${encodeURIComponent(text)}`,
62	      '_blank',
63	      'noopener,noreferrer',
64	    );
65	  };
66	
67	  return (
68	    <Dialog open={open} onOpenChange={onOpenChange}>
69	      <DialogContent
70	        className="max-w-lg border-white/40 bg-white/80 backdrop-blur-xl dark:border-white/10 dark:bg-black/60 sm:rounded-2xl"
71	        data-testid="tv-report-modal"
72	      >
73	        <DialogHeader>
74	          <DialogTitle className="flex items-center gap-2 font-momma text-[#2D362E] dark:text-[#E6DCCF]">
75	            <span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-2xl bg-[#57715B]/10">
76	              <FileText className="h-4 w-4 text-[#57715B] dark:text-[#8FAE94]" aria-hidden />
77	            </span>
78	            Relatório diário
79	          </DialogTitle>
80	          <DialogDescription>
81	            Texto pronto para enviar aos sócios — faturamento do dia, acumulado
82	            do mês, meta e projeção.
83	          </DialogDescription>
84	        </DialogHeader>
85	
86	        <div className="space-y-3">
87	          <label className="flex flex-wrap items-center gap-2 text-sm font-medium text-[#5F6F63]">
88	            Data-base
89	            <Input
90	              type="date"
91	              value={baseDate}
92	              max={yesterday}
93	              onChange={(e) => {
94	                const value = e.target.value;
95	                if (!value) return;
96	                // Clamp: relatório fala de dia FECHADO — digitação além de
