99	                setBaseDate(value > yesterday ? yesterday : value);
100	              }}
101	              className="w-auto rounded-xl border-[#57715B]/15 bg-white/70 tabular-nums focus-visible:ring-[#57715B]/30 dark:bg-black/20"
102	              aria-label="Data-base do relatório"
103	              data-testid="tv-report-date"
104	            />
105	          </label>
106	
107	          <div className="max-h-[50vh] overflow-y-auto rounded-2xl border border-white/20 bg-white/40 p-4 shadow-sm backdrop-blur-md dark:border-white/10 dark:bg-black/20">
108	            {reportQuery.isLoading ? (
109	              <div className="space-y-2 animate-pulse" aria-label="Gerando relatório">
110	                <div className="h-3 w-2/3 rounded-full bg-[#57715B]/10" />
111	                <div className="h-3 w-1/2 rounded-full bg-[#57715B]/10" />
112	                <div className="h-3 w-3/4 rounded-full bg-[#57715B]/10" />
113	                <div className="h-3 w-2/5 rounded-full bg-[#57715B]/10" />
114	              </div>
115	            ) : reportQuery.isError ? (
116	              <p className="text-sm text-amber-600">
117	                Não foi possível gerar o relatório. Tente novamente em instantes.
118	              </p>
119	            ) : (
120	              <pre
121	                className="whitespace-pre-wrap break-words font-mono text-xs leading-relaxed text-[#2D362E] tabular-nums dark:text-[#E6DCCF]"
122	                data-testid="tv-report-preview"
123	              >
124	                {text}
125	              </pre>
126	            )}
127	          </div>
128	        </div>
129	
130	        <DialogFooter className="gap-2 sm:gap-2">
131	          <Button
132	            type="button"
133	            variant="outline"
134	            onClick={handleCopy}
135	            disabled={!text}
136	            data-mia-action="copiar-relatorio-painel-tv"
137	            className="rounded-full border-[#57715B]/20 text-[#57715B] hover:bg-[#57715B]/10 dark:text-[#8FAE94]"
138	          >
139	            <Copy className="mr-2 h-4 w-4" aria-hidden />
140	            Copiar
141	          </Button>
142	          <Button
143	            type="button"
144	            onClick={handleWhatsApp}
145	            disabled={!text}
146	            data-mia-action="compartilhar-relatorio-whatsapp"
147	            className="rounded-full bg-[#57715B] text-white shadow-lg shadow-[#57715B]/20 hover:bg-[#465b49]"
148	          >
149	            <MessageCircle className="mr-2 h-4 w-4" aria-hidden />
150	            WhatsApp
151	          </Button>
152	        </DialogFooter>
153	      </DialogContent>
154	    </Dialog>
155	  );
156	}
