266	const pad = (n: number) => String(n).padStart(2, '0');
267	const isoLocal = (d: Date) =>
268	  `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
269	const plusDays = (d: Date, n: number) => {
