282	/**
283	 * Fixture relativa a HOJE (robusta a qualquer data de execução):
284	 * - loja 4 com meta mensal própria (100k) + diário oficial de R$ 1.000 nos
285	 *   dias JÁ FECHADOS da semana corrente + R$ 999 oficial parcial de hoje +
286	 *   flash live de R$ 1.500 hoje;
287	 * - loja 3 Degust SEM linha própria em `metas_mensais` (só a linha da rede);
288	 * - quando a semana corrente não começa no dia 1º, um dia de semana ANTERIOR
289	 *   do mês entra com R$ 7.777 (redistribui o target, fora do achieved).
290	 */
291	function setupWeeklyGoalFixture() {
292	  const now = new Date();
293	  const todayIso = isoLocal(now);
294	  const firstOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
295	  const dowFromMonday = (now.getDay() + 6) % 7;
296	  const monday = plusDays(now, -dowFromMonday);
297	  const weekStart =
298	    monday.getTime() < firstOfMonth.getTime() ? firstOfMonth : monday;
299	
300	  const closedDays: string[] = [];
301	  for (let d = new Date(weekStart); isoLocal(d) < todayIso; d = plusDays(d, 1)) {
302	    closedDays.push(isoLocal(d));
303	  }
304	
305	  const daily: DailyRow[] = [
306	    ...closedDays.map((data) => ({
307	      data,
308	      loja_id: 4,
309	      total_faturado: 1_000,
310	      total_cupons: 10,
311	    })),
312	    // hoje TEM oficial parcial (999) — no live o flash (1.500) deve prevalecer
313	    { data: todayIso, loja_id: 4, total_faturado: 999, total_cupons: 9 },
314	  ];
315	  if (weekStart.getTime() > firstOfMonth.getTime()) {
316	    daily.push({
317	      data: isoLocal(firstOfMonth),
318	      loja_id: 4,
319	      total_faturado: 7_777,
320	      total_cupons: 7,
321	    });
322	  }
323	
324	  mockState.tables = {
325	    lojas: [
326	      { id: 4, nome: 'Momma Lago Sul', tipo: 'Loja' },
327	      { id: 3, nome: 'Momma Asa Norte', tipo: 'Loja' },
328	    ],
329	    degust_stores: [
330	      { loja_id: 4, degust_loja_codigo: 1 },
331	      { loja_id: 3, degust_loja_codigo: 5 },
332	    ],
333	    metas_mensais: [
334	      // Linha da REDE (loja_id NULL) NÃO vira meta de loja nenhuma
335	      {
336	        loja_id: null,
337	        ano: now.getFullYear(),
338	        mes: now.getMonth() + 1,
339	        valor_meta: 999_999,
340	      },
341	      {
342	        loja_id: 4,
343	        ano: now.getFullYear(),
344	        mes: now.getMonth() + 1,
345	        valor_meta: 100_000,
346	      },
347	    ],
348	  };
349	
350	  const brToday = `${pad(now.getDate())}/${pad(now.getMonth() + 1)}/${now.getFullYear()} 12:00:00`;
351	  mockState.edge = (body) => {
352	    if (body.includeHourly) return { hourly: [] };
353	    if (body.includeDeliverySplit) return { deliverySplit: [] };
354	    return {
355	      flash: [
356	        {
357	          loja_id: 4,
358	          nome_loja: 'Momma Lago Sul',
359	          total_vendas: 1_500,
360	          total_cupons: 12,
361	          ticket_medio: 125,
362	          qtd_produtos: 0,
363	          caixa_aberto: true,
364	          ultima_atualizacao: brToday,
365	        },
366	      ],
367	      daily,
368	    };
369	  };
370	
371	  return { now, todayIso, closedDays, daily };
372	}
