374	describe('useTvDashboardData — weeklyGoal por loja (meta semanal)', () => {
375	  it('live: loja com meta tem weeklyGoal — achieved soma seg→hoje com HOJE do flash; loja sem meta → null', async () => {
376	    const { now, todayIso, closedDays, daily } = setupWeeklyGoalFixture();
377	    const { result, unmount } = renderHook(() => useTvDashboardData(), {
378	      wrapper: createWrapper(),
379	    });
380	
381	    // seg→ontem oficiais (1k/dia) + hoje pelo FLASH (1.500, não o 999 oficial)
382	    const expectedAchieved = closedDays.length * 1_000 + 1_500;
383	    await waitFor(() => {
384	      expect(
385	        result.current.stores.find((s) => s.lojaId === 4)?.weeklyGoal?.achieved,
386	      ).toBe(expectedAchieved);
387	    });
388	
389	    const goal = result.current.stores.find((s) => s.lojaId === 4)?.weeklyGoal;
390	    if (!goal) throw new Error('weeklyGoal ausente para a loja com meta');
391	    // Target = MESMA redistribuição do helper puro sobre o mesmo realizado
392	    // (déficit/superávit das semanas passadas realoca a meta da corrente).
393	    const realizado = new Map<string, number>(
394	      daily.map((d) => [d.data, d.total_faturado]),
395	    );
396	    realizado.set(todayIso, 1_500); // hoje = flash live
397	    const esperado = currentWeekGoal(100_000, realizado, now);
398	    if (!esperado) throw new Error('fixture inválida: meta positiva sem goal');
399	    expect(goal.target).toBeCloseTo(esperado.target, 6);
400	    expect(goal.pct).toBeCloseTo((expectedAchieved / esperado.target) * 100, 6);
401	
402	    // Loja Degust SEM linha própria em metas_mensais → null (rede não conta)
403	    expect(
404	      result.current.stores.find((s) => s.lojaId === 3)?.weeklyGoal,
405	    ).toBeNull();
406	    unmount();
407	  });
