416	    // Sem flash (modo passado): hoje entra com o oficial parcial (999)
417	    const expectedAchieved = closedDays.length * 1_000 + 999;
418	    await waitFor(() => {
419	      expect(
420	        result.current.stores.find((s) => s.lojaId === 4)?.weeklyGoal?.achieved,
421	      ).toBe(expectedAchieved);
422	    });
423	    expect(result.current.isLive).toBe(false);
424	    unmount();
425	  });
426	});
