122	  // ── Meta mensal (R4): mês/ano selecionável, rede + por loja ──
123	  const [mensalAno, setMensalAno] = useState(() => new Date().getFullYear());
124	  const [mensalMes, setMensalMes] = useState(() => new Date().getMonth() + 1);
125	  const [showMetasPorLoja, setShowMetasPorLoja] = useState(false);
126	  const mensaisQuery = useQuery({
127	    queryKey: ['tv-metas', 'mensais', mensalAno, mensalMes],
128	    queryFn: () => fetchMetasMensais(mensalAno, mensalMes),
129	  });
130	
131	  const [redeValue, setRedeValue] = useState('');
132	  const [lojaMensalValues, setLojaMensalValues] = useState<Record<number, string>>({});
133	  // Inicializa a partir do banco UMA vez por mês/ano selecionado (chave
134	  // `${ano}:${mes}`). Guard obrigatório: refetch (ex.: refetchOnWindowFocus
135	  // do QueryClient default) troca a REFERÊNCIA de `mensaisQuery.data` e,
136	  // sem o guard, sobrescrevia digitação ainda não salva. Re-inicializa
137	  // SOMENTE quando o usuário troca mês/ano (chave muda) — nunca por refetch.
138	  const mensalInitKey = useRef<string | null>(null);
139	  useEffect(() => {
140	    const rows = mensaisQuery.data;
141	    if (!rows) return;
142	    const key = `${mensalAno}:${mensalMes}`;
143	    if (mensalInitKey.current === key) return;
144	    mensalInitKey.current = key;
145	    const rede = rows.find((r) => r.loja_id === null);
146	    setRedeValue(rede && rede.valor_meta > 0 ? String(rede.valor_meta) : '');
147	    const next: Record<number, string> = {};
148	    for (const row of rows) {
149	      if (row.loja_id != null && row.valor_meta > 0) {
150	        next[row.loja_id] = String(row.valor_meta);
151	      }
152	    }
153	    setLojaMensalValues(next);
154	  }, [mensaisQuery.data, mensalAno, mensalMes]);
155	
156	  const saveMensalMutation = useMutation({
157	    mutationFn: async () => {
158	      const rows = mensaisQuery.data ?? [];
159	      // Linha da REDE (loja_id NULL): o upsert do PostgREST NÃO casa NULL
160	      // no onConflict — select prévio (já no cache da query) + update por
161	      // id quando existe; insert caso contrário.
162	      const redeRow = rows.find((r) => r.loja_id === null) ?? null;
163	      const redeParsed = parseMetaInput(redeValue);
164	      if (redeParsed != null) {
165	        if (redeRow) {
166	          const { error } = await supabase
167	            .from('metas_mensais')
168	            .update({ valor_meta: redeParsed })
169	            .eq('id', redeRow.id);
170	          if (error) throw error;
171	        } else {
172	          const { error } = await supabase.from('metas_mensais').insert({
173	            loja_id: null,
174	            ano: mensalAno,
175	            mes: mensalMes,
176	            valor_meta: redeParsed,
177	          });
178	          if (error) throw error;
179	        }
180	      } else if (redeRow && redeValue.trim() === '') {
181	        // Campo esvaziado que TINHA meta → 0 (semanticamente sem meta)
182	        const { error } = await supabase
183	          .from('metas_mensais')
184	          .update({ valor_meta: 0 })
185	          .eq('id', redeRow.id);
186	        if (error) throw error;
187	      }
188	
189	      // Por loja: loja_id não-nulo casa normal no onConflict
190	      const persistedLojaIds = new Set(
191	        rows
192	          .filter((r) => r.loja_id != null && r.valor_meta > 0)
193	          .map((r) => r.loja_id as number),
194	      );
195	      const lojaRows: Array<{
196	        loja_id: number;
197	        ano: number;
198	        mes: number;
199	        valor_meta: number;
200	      }> = [];
201	      for (const loja of lojasQuery.data ?? []) {
202	        const raw = lojaMensalValues[loja.id] ?? '';
203	        const parsed = parseMetaInput(raw);
204	        if (parsed != null) {
205	          lojaRows.push({
206	            loja_id: loja.id,
207	            ano: mensalAno,
208	            mes: mensalMes,
209	            valor_meta: parsed,
210	          });
211	        } else if (raw.trim() === '' && persistedLojaIds.has(loja.id)) {
212	          lojaRows.push({
213	            loja_id: loja.id,
214	            ano: mensalAno,
215	            mes: mensalMes,
216	            valor_meta: 0,
217	          });
218	        }
219	      }
220	      if (lojaRows.length > 0) {
221	        const { error } = await supabase
222	          .from('metas_mensais')
223	          .upsert(lojaRows, { onConflict: 'loja_id,ano,mes' });
224	        if (error) throw error;
225	      }
226	    },
227	    onSuccess: () => {
228	      toast.success('Meta mensal salva');
229	      queryClient.invalidateQueries({ queryKey: ['tv-metas', 'mensais'] });
230	      queryClient.invalidateQueries({ queryKey: tvDashboardKeys.metasMensais() });
231	    },
232	    onError: (error: Error) => {
233	      toast.error('Erro ao salvar meta mensal', {
234	        description: error.message || 'Tente novamente em instantes.',
235	      });
236	    },
237	  });
